public class PayableExample {
    interface Payable {
        double calculatePay();
    }

    static class Employee implements Payable {
        double hours, rate;
        Employee(double hours, double rate) { this.hours = hours; this.rate = rate; }
        public double calculatePay() { return hours * rate; }
    }

    static class Freelancer implements Payable {
        double projectFee;
        Freelancer(double projectFee) { this.projectFee = projectFee; }
        public double calculatePay() { return projectFee; }
    }

    public static void main(String[] args) {
        Payable[] people = { new Employee(40, 20), new Freelancer(500) };
        for (Payable p : people) {
            System.out.println("Pay: " + p.calculatePay());
        }
    }
}
